void mainImage(out vec4 fragColor,in vec2 fragCoord){
 vec2 p=(fragCoord-.5*iResolution.xy)/iResolution.y;
 float pix=1.0/iResolution.y;
 float t=vrchPhase_speed();
 float strike=smoothstep(0.0,.85,uParam_accent);
 float r=max(length(p),.0005);
 float th=atan(p.y,p.x);
 // Both hands visible: their spread opens the rosette, their height deepens the petals.
 float lOn=smoothstep(.02,.2,uParam_left_y),rOn=smoothstep(.02,.2,uParam_right_y);
 float both=lOn*rOn*uParam_open;
 float spread=both*smoothstep(.1,.7,abs(uParam_left_x-uParam_right_x));
 float lift=both*smoothstep(.3,.9,.5*(uParam_left_y+uParam_right_y));
 float petals=clamp(floor(uParam_petals+.5),3.0,16.0);
 float count=clamp(floor(uParam_rings+.5),6.0,28.0);
 float size=(.25+uParam_bloom*.12)*(1.0+.45*spread);
 float amp=size*(.075+.07*lift);
 float ripple=uParam_motion*.012*sin(r*44.0-t*6.0);
 vec3 ink=uParam_color.rgb;
 float lines=0.0,sparks=0.0;
 // Within a band every ring angle advances by a fixed step, so the ring phasors are rotated
 // instead of re-evaluated; the spark phasor advances by .9 per ring.
 float twistStep=.35+uParam_twist*.9,invR2=1.0/(r*r);
 vec2 ringStep=vec2(cos(twistStep),sin(twistStep)),ringW=vec2(1.0,0.0);
 float sparkA=th*petals-t*1.4;
 vec2 sparkW=vec2(cos(sparkA),sin(sparkA)),sparkStep=vec2(cos(.9),sin(.9));
 // Rings of each band in their own loop, two rings per iteration: the phasors
 // alternate between two variables, so nothing is copied between rings.
 float w=pix*.5,w2=w*w,countM1=count-1.0;
 int inner=int(ceil(.5*countM1-1e-4)),total=int(count+.5);
 for(int band=0;band<2;band++){
  float fb=float(band);
  float m=petals*(1.0+fb),a=amp*(1.0+.5*fb);
  int first=band==0?0:inner,last=band==0?inner:total;
  float fi=float(first),k=fi/countM1;
  float R=size*(band==0?mix(.28,.62,k*2.0):mix(.86,1.34,k*2.0-1.0));
  float dR=size*(band==0?.68:.96)/countM1;
  float ang=m*th+fi*twistStep+t*mix(.25,-.18,fb);
  vec2 ringA=vec2(cos(ang),sin(ang)),ringB;
  vec2 sparkB;
  int n=last-first;
  for(int j=0;j<14;j++){
   if(2*j>=n)break;
   {float f=R+a*ringA.y+ripple,fd=a*m*ringA.x;
    float d=(r-f)*inversesqrt(1.0+fd*fd*invR2);
    float line=w2/(d*d+w2);lines+=line;
    float sp=.5+.5*sparkW.y,sp2=sp*sp,sp4=sp2*sp2,sp8=sp4*sp4;
    sparks+=line*uParam_lace*(sp8*sp8*sp8);
    ringB=vec2(ringA.x*ringStep.x-ringA.y*ringStep.y,ringA.y*ringStep.x+ringA.x*ringStep.y);
    sparkB=vec2(sparkW.x*sparkStep.x-sparkW.y*sparkStep.y,sparkW.y*sparkStep.x+sparkW.x*sparkStep.y);
    R+=dR;}
   if(2*j+1>=n){sparkW=sparkB;break;}
   {float f=R+a*ringB.y+ripple,fd=a*m*ringB.x;
    float d=(r-f)*inversesqrt(1.0+fd*fd*invR2);
    float line=w2/(d*d+w2);lines+=line;
    float sp=.5+.5*sparkB.y,sp2=sp*sp,sp4=sp2*sp2,sp8=sp4*sp4;
    sparks+=line*uParam_lace*(sp8*sp8*sp8);
    ringA=vec2(ringB.x*ringStep.x-ringB.y*ringStep.y,ringB.y*ringStep.x+ringB.x*ringStep.y);
    sparkW=vec2(sparkB.x*sparkStep.x-sparkB.y*sparkStep.y,sparkB.y*sparkStep.x+sparkB.x*sparkStep.y);
    R+=dR;}
  }
 }
 float wave=strike*strike*exp(-abs(r-(.05+(1.0-strike)*1.1))*70.0);
 float halo=exp(-abs(r-size*.95)*28.0)*.012;
 vec3 c=ink*(lines*.42+halo)+mix(ink,vec3(1.0),.55)*(sparks*1.6+wave*.3);
 c+=mix(ink,vec3(1.0),.6)*exp(-r*r*900.0)*.35;
 c*=(.55+uParam_glow*1.1)*smoothstep(1.25,.35,r);
 fragColor=vec4(1.0-exp(-c*1.3),1.0);
}
